def parse_prepositional_phrase():
    return llist('prep-phrase', parse_word(prepositions),
                 parse_noun_phrase())

def parse_sentence():
    return llist('sentence', parse_noun_phrase(), parse_verb_phrase())
def parse_verb_phrase():
    def maybe_extend(verb_phrase):
        return amb(verb_phrase,
                   maybe_extend(llist('verb-phrase', verb_phrase,
                                      parse_prepositional_phrase())))
    return maybe_extend(parse_word(verbs))

def parse_simple_noun_phrase():
    return llist('simple-noun-phrase', parse_word(articles),
                 parse_word(nouns))
def parse_noun_phrase():
    def maybe_extend(noun_phrase):
        return amb(noun_phrase,
                   maybe_extend(llist('noun-phrase', noun_phrase,
                                      parse_prepositional_phrase())))
    return maybe_extend(parse_simple_noun_phrase())

def parse_verb_phrase():
    return amb(parse_word(verbs),
               llist('verb-phrase', parse_verb_phrase(),
                     parse_prepositional_phrase()))

def distinct(items):
    if is_none(items):
        return True
    elif is_none(tail(items)):
        return True
    elif is_none(member(head(items), tail(items))):
        return distinct(tail(items))
    else:
        return False
